/**
 * resolveImage — look up a real Ecoy photograph on the Shopify CDN by
 * product, colour and angle, instead of pasting a hash-named filename
 * into a component.
 *
 * Backed by assets/cdn-catalog.json (generated by build_cdn_catalog.py
 * from shopify-upload-manifest.json — 6,350 live-colourway images).
 * Regenerate the catalog after any photography upload; never hand-edit it.
 *
 * Usage in a component:
 *
 *   import catalog from './cdn-catalog.json'
 *   import { resolveImage } from './resolveImage.js'
 *
 *   const hero = resolveImage(catalog, { product: 'BambooSheetSet', colour: 'Dusk' })
 *   // hero.url -> https://cdn.shopify.com/.../BambooSheetSet-Solid-Dusk-High45-NoTalent-Real-01.webp
 *
 *   <img src={hero?.url} alt={`${hero.product} in ${hero.colour}`} />
 *
 * If nothing matches, resolveImage returns null — always check before
 * rendering rather than falling back to a hardcoded filename.
 */

/**
 * @param {object} catalog - the parsed cdn-catalog.json
 * @param {object} query
 * @param {string} query.product - e.g. "BambooSheetSet" (see naming.json products.solid/products.stripe)
 * @param {string} [query.pattern] - "Solid" | "Stripe" | "Polka"; omit for products with no pattern (quilts, pillows, protector)
 * @param {string} [query.colour] - e.g. "Dusk", or a two-colour pair like "BurntOrangexWhite"; omit for no-colourway products
 * @param {string} [query.angle] - a specific angle; omit to use the angle preference order (High45 first)
 * @param {string} [query.people] - "NoTalent" | "Talent"; omit to accept either
 * @param {string} [query.source] - "Real" | "AI"; omit to prefer Real over AI
 * @param {boolean} [query.allowNotYetLive=false] - include images flagged notYetLive (see build_cdn_catalog.py)
 * @returns {object|null} { url, filename, angle, people, source, product, pattern, colour } or null
 */
export function resolveImage(catalog, query) {
  const {
    product,
    pattern = "_none",
    colour = "_none",
    angle,
    people,
    source,
    allowNotYetLive = false,
  } = query;

  if (!product) return null;
  const byPattern = catalog.index[product];
  if (!byPattern) return null;
  const byColour = byPattern[pattern];
  if (!byColour) return null;
  const byAngle = byColour[colour];
  if (!byColour[colour]) return null;

  const anglesToTry = angle ? [angle] : catalog.anglePreference;

  for (const a of anglesToTry) {
    const candidates = byAngle[a];
    if (!candidates || candidates.length === 0) continue;

    const usable = allowNotYetLive
      ? candidates
      : candidates.filter((c) => !c.notYetLive);
    if (usable.length === 0) continue;

    const filtered = pickBest(usable, { people, source });
    if (filtered) {
      return { ...filtered, product, pattern, colour, angle: a };
    }
  }

  return null;
}

/**
 * List every candidate for a product/pattern/colour/angle, in preference
 * order, instead of just the single best match. Useful for a gallery or
 * a colourway grid that needs several frames of the same shot.
 *
 * @returns {object[]} possibly empty
 */
export function listImages(catalog, query) {
  const { product, pattern = "_none", colour = "_none", angle, allowNotYetLive = false } = query;
  if (!product) return [];
  const byAngle = catalog.index[product]?.[pattern]?.[colour];
  if (!byAngle) return [];

  const anglesToTry = angle ? [angle] : catalog.anglePreference;
  const out = [];
  for (const a of anglesToTry) {
    const candidates = byAngle[a] || [];
    for (const c of candidates) {
      if (!allowNotYetLive && c.notYetLive) continue;
      out.push({ ...c, product, pattern, colour, angle: a });
    }
  }
  return out;
}

function pickBest(candidates, { people, source }) {
  let pool = candidates;
  if (people) {
    const withPeople = pool.filter((c) => c.people === people);
    if (withPeople.length) pool = withPeople;
  }
  if (source) {
    const withSource = pool.filter((c) => c.source === source);
    if (withSource.length) pool = withSource;
  } else {
    // Prefer real photography over AI when the caller didn't specify.
    const real = pool.filter((c) => c.source === "Real");
    if (real.length) pool = real;
  }
  return pool[0] || null;
}
